Insert into MMSGMSGDEF
   (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME)
 values
   ('RAS-0302','RAS','RAS-0302 : Cannot raise an event. The elapsed time of current tool status is less than the time for tool event setup. Check tool event setup.','RAS-0302 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태의 경과 시간값이 TOOL 이벤트 설정시간보다 작습니다. TOOL 이벤트 설정을 확인하십시요.','RAS-0302 : Event kann nicht generiert werden. Die abgelaufene Zeit des aktuellen Tool Status ist geringer als die die fuer Tool Event Setup. Bitte ueberpruefen Sie Tool Event Setup.','ADMIN','20100507153339',' ',' ');
Insert into MMSGMSGDEF
   (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME)
 values
   ('RAS-0303','RAS','RAS-0303 : Cannot raise an event. The elapsed time of current tool status is higher than the time for tool event setup. Check tool event setup.','RAS-0303 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태의 경과 시간값이 TOOL 이벤트 설정시간보다 큽니다. TOOL 이벤트 설정을 확인하십시요.','RAS-0303 : Event kann nicht generiert werden. Die abgelaufene Zeit des aktuellen Tool Status ist hoeher als die die fuer Tool Event Setup. Bitte ueberpruefen Sie Tool Event Setup.','ADMIN','20100507153436',' ',' ');
